# vle.S -- directed test: the unit-stride loads vle<eew>.v (unmasked) at VLEN 128, a doubleword at a
# time through the scalar LSU (docs/PLAN-2026-11-25-vector.md §8). Generated by the session's
# vle_gen.py; src byte j is (7j + 1) mod 256. Every result is stored whole (vs1r.v) and checked.
#
#   1  VS Off: vle8.v is an illegal instruction
#   2  e8, m1, vl 16, an aligned base
#   3  e32, m1, vl 4, a base 4 past a doubleword
#   4  e8, m1, vl 5, an odd base: the tail keeps the old bytes
#   5  e16, m2, vl 13, a base 6 past a doubleword: both registers
#   6  e64, m8, vl 16: all eight registers
#   7  a fractional EMUL: vle8.v at e64, m1 (EMUL 1/8), vl 2: one register, two bytes
#   8  an EMUL above 8 (vle64.v at e8, m8) is illegal, as is any at vill
#   9  vl 0 at address 0 (no memory there): nothing is read, nothing faults
#  10  vstart 3: the prestart bytes keep the old ones, and vstart reads 0 after
#  11  S-mode, Sv39: e8, vl 16 from 6 bytes before an unmapped page takes a load page fault at
#      element 6 (tval the page, vstart 6, elements 0..5 loaded); the handler maps it, the retry loads
#      the rest
#  12  ...and with vl 6, the same access touches nothing in the unmapped page: no fault
#
# A trap is counted in s5 (mcause in s3, mtval in s4); with s6 nonzero the handler records vstart in
# s9, writes s6 to the PTE at s7 and retries, else returns past the instruction. An ecall from S ends
# the run with the verdict in a0.
#   tohost = 1 PASS, else FAIL with test# = tohost>>1

	.option	arch, +v
#define VSTART 0x008

	.section .text.init,"ax",@progbits
	.globl _start
_start:
	la	t0, trap_handler
	csrw	mtvec, t0
	li	s5, 0
	li	s6, 0
	csrw	mstatus, x0
	la	a3, dst

	#---------------- 1: VS Off
	la	a2, src
	vle8.v	v1, (a2)
	li	t2, 1
	bne	s5, t2, fail1
	li	t0, 1 << 9		# VS Initial
	csrw	mstatus, t0
	li	s5, 0

	#---------------- 2: e8, m1, vl 16, aligned
	li	t0, -1
	vsetvli	t1, x0, e8, m1, ta, ma
	vmv.v.x	v1, t0
	vsetivli	t0, 16, e8, m1, ta, ma
	la	a2, src
	vle8.v	v1, (a2)
	vmv1r.v	v31, v1
	li	a0, 0x322b241d160f0801
	li	a1, 0x6a635c554e474039
	call	chk
	bnez	a0, fail2
	#---------------- 3: e32, vl 4, base + 4
	li	t0, -1
	vsetvli	t1, x0, e8, m1, ta, ma
	vmv.v.x	v2, t0
	vsetivli	t0, 4, e32, m1, ta, ma
	la	a2, src
	addi	a2, a2, 4
	vle32.v	v2, (a2)
	vmv1r.v	v31, v2
	li	a0, 0x4e474039322b241d
	li	a1, 0x867f78716a635c55
	call	chk
	bnez	a0, fail3
	#---------------- 4: e8, vl 5, base + 3
	li	t0, -1
	vsetvli	t1, x0, e8, m1, ta, ma
	vmv.v.x	v3, t0
	vsetivli	t0, 5, e8, m1, ta, ma
	la	a2, src
	addi	a2, a2, 3
	vle8.v	v3, (a2)
	vmv1r.v	v31, v3
	li	a0, 0xffffff322b241d16
	li	a1, 0xffffffffffffffff
	call	chk
	bnez	a0, fail4
	#---------------- 5: e16, m2, vl 13, base + 6
	li	t0, -1
	vsetvli	t1, x0, e8, m2, ta, ma
	vmv.v.x	v4, t0
	vsetivli	t0, 13, e16, m2, ta, ma
	la	a2, src
	addi	a2, a2, 6
	vle16.v	v4, (a2)
	vmv1r.v	v31, v4
	li	a0, 0x5c554e474039322b
	li	a1, 0x948d867f78716a63
	call	chk
	bnez	a0, fail5
	vmv1r.v	v31, v5
	li	a0, 0xccc5beb7b0a9a29b
	li	a1, 0xffffffffffffdad3
	call	chk
	bnez	a0, fail5
	#---------------- 6: e64, m8, vl 16
	li	t0, -1
	vsetvli	t1, x0, e8, m8, ta, ma
	vmv.v.x	v8, t0
	vsetivli	t0, 16, e64, m8, ta, ma
	la	a2, src
	addi	a2, a2, 8
	vle64.v	v8, (a2)
	vmv1r.v	v31, v8
	li	a0, 0x6a635c554e474039
	li	a1, 0xa29b948d867f7871
	call	chk
	bnez	a0, fail6
	vmv1r.v	v31, v9
	li	a0, 0xdad3ccc5beb7b0a9
	li	a1, 0x120b04fdf6efe8e1
	call	chk
	bnez	a0, fail6
	vmv1r.v	v31, v10
	li	a0, 0x4a433c352e272019
	li	a1, 0x827b746d665f5851
	call	chk
	bnez	a0, fail6
	vmv1r.v	v31, v11
	li	a0, 0xbab3aca59e979089
	li	a1, 0xf2ebe4ddd6cfc8c1
	call	chk
	bnez	a0, fail6
	vmv1r.v	v31, v12
	li	a0, 0x2a231c150e0700f9
	li	a1, 0x625b544d463f3831
	call	chk
	bnez	a0, fail6
	vmv1r.v	v31, v13
	li	a0, 0x9a938c857e777069
	li	a1, 0xd2cbc4bdb6afa8a1
	call	chk
	bnez	a0, fail6
	vmv1r.v	v31, v14
	li	a0, 0x0a03fcf5eee7e0d9
	li	a1, 0x423b342d261f1811
	call	chk
	bnez	a0, fail6
	vmv1r.v	v31, v15
	li	a0, 0x7a736c655e575049
	li	a1, 0xb2aba49d968f8881
	call	chk
	bnez	a0, fail6
	#---------------- 7: fractional EMUL
	li	t0, -1
	vsetvli	t1, x0, e8, m1, ta, ma
	vmv.v.x	v16, t0
	vsetivli	t0, 2, e64, m1, ta, ma
	la	a2, src
	addi	a2, a2, 1
	vle8.v	v16, (a2)
	vmv1r.v	v31, v16
	li	a0, 0xffffffffffff0f08
	li	a1, 0xffffffffffffffff
	call	chk
	bnez	a0, fail7
	#---------------- 8: illegal EMUL, vill
	vsetivli	t0, 16, e8, m8, ta, ma
	la	a2, src
	vle64.v	v16, (a2)
	li	t2, 1
	bne	s5, t2, fail8
	li	a1, 0x100
	li	a0, 4
	vsetvl	t0, a0, a1
	vle8.v	v16, (a2)
	li	t2, 2
	bne	s5, t2, fail8
	li	s5, 0
	#---------------- 9: vl 0 at address 0
	li	t0, -1
	vsetvli	t1, x0, e8, m1, ta, ma
	vmv.v.x	v17, t0
	vsetivli	t0, 0, e8, m1, ta, ma
	li	a2, 0
	vle8.v	v17, (a2)
	bnez	s5, fail9
	vmv1r.v	v31, v17
	li	a0, 0xffffffffffffffff
	li	a1, 0xffffffffffffffff
	call	chk
	bnez	a0, fail9
	#---------------- 10: vstart 3
	li	t0, -1
	vsetvli	t1, x0, e8, m1, ta, ma
	vmv.v.x	v18, t0
	vsetivli	t0, 16, e8, m1, ta, ma
	li	t0, 3
	csrw	VSTART, t0
	la	a2, src
	vle8.v	v18, (a2)
	csrr	t1, VSTART
	bnez	t1, fail10
	vmv1r.v	v31, v18
	li	a0, 0x322b241d16ffffff
	li	a1, 0x6a635c554e474039
	call	chk
	bnez	a0, fail10
	bnez	s5, fail10
	#---------------- 11, 12: S-mode, page faults
	# Sv39: 0x8000_0000 -> itself as a gigapage (RWX); 0x4000_0000 -> pagea, 0x4000_1000 -> pageb
	# (4 KiB pages, pt0[1] invalid until the handler writes it)
	la	t0, pt2
	la	t1, pt1
	srli	t1, t1, 12
	slli	t1, t1, 10
	ori	t1, t1, 1
	sd	t1, 8(t0)
	li	t1, (0x80000 << 10) | 0xcf
	sd	t1, 16(t0)
	la	t0, pt1
	la	t1, pt0
	srli	t1, t1, 12
	slli	t1, t1, 10
	ori	t1, t1, 1
	sd	t1, 0(t0)
	la	t0, pt0
	la	t1, pagea
	srli	t1, t1, 12
	slli	t1, t1, 10
	ori	t1, t1, 0xc7
	sd	t1, 0(t0)
	la	t0, pt2
	srli	t0, t0, 12
	li	t1, 8 << 60
	or	t0, t0, t1
	csrw	satp, t0
	sfence.vma
	li	t0, 3 << 11
	csrc	mstatus, t0
	li	t0, 1 << 11
	csrs	mstatus, t0
	la	t0, s_start
	csrw	mepc, t0
	mret

s_start:
	# src bytes 0..5 at 0x4000_0ffa, 6..15 at 0x4000_1000 (pageb, through the gigapage)
	la	a2, src
	li	a4, 0x40000ffa
	li	t2, 6
1:	lbu	t0, 0(a2)
	sb	t0, 0(a4)
	addi	a2, a2, 1
	addi	a4, a4, 1
	addi	t2, t2, -1
	bnez	t2, 1b
	la	a4, pageb
	li	t2, 10
1:	lbu	t0, 0(a2)
	sb	t0, 0(a4)
	addi	a2, a2, 1
	addi	a4, a4, 1
	addi	t2, t2, -1
	bnez	t2, 1b
	# 12 first: vl 6 ends at the page; nothing is read past it
	li	t0, -1
	vsetvli	t1, x0, e8, m1, ta, ma
	vmv.v.x	v20, t0
	vsetivli	t0, 6, e8, m1, ta, ma
	li	a4, 0x40000ffa
	vle8.v	v20, (a4)
	bnez	s5, fail12
	vmv1r.v	v31, v20
	li	a0, 0xffff241d160f0801
	li	a1, 0xffffffffffffffff
	call	chk
	bnez	a0, fail12s
	# 11: vl 16 faults at element 6
	la	s7, pt0
	addi	s7, s7, 8
	la	s6, pageb
	srli	s6, s6, 12
	slli	s6, s6, 10
	ori	s6, s6, 0xc7
	li	t0, -1
	vsetvli	t1, x0, e8, m1, ta, ma
	vmv.v.x	v21, t0
	vsetivli	t0, 16, e8, m1, ta, ma
	li	a4, 0x40000ffa
	vle8.v	v21, (a4)
	li	t1, 1
	bne	s5, t1, fail11s
	li	t1, 13
	bne	s3, t1, fail11s
	li	t1, 0x40001000
	bne	s4, t1, fail11s
	li	t1, 6
	bne	s9, t1, fail11s
	vmv1r.v	v31, v21
	li	a0, 0x322b241d160f0801
	li	a1, 0x6a635c554e474039
	call	chk
	bnez	a0, fail11s
	li	a0, 1
	ecall
fail1:	li	a0, 3
	j	done_m
fail2:	li	a0, 5
	j	done_m
fail3:	li	a0, 7
	j	done_m
fail4:	li	a0, 9
	j	done_m
fail5:	li	a0, 11
	j	done_m
fail6:	li	a0, 13
	j	done_m
fail7:	li	a0, 15
	j	done_m
fail8:	li	a0, 17
	j	done_m
fail9:	li	a0, 19
	j	done_m
fail10:	li	a0, 21
	j	done_m
fail11s:	li	a0, 23
	ecall
fail12:	li	a0, 25
	ecall
fail12s:	li	a0, 25
	ecall

	# a0 = 0 when v31 holds {a1, a0}
chk:	vs1r.v	v31, (a3)
	ld	t4, 0(a3)
	ld	t5, 8(a3)
	xor	t4, t4, a0
	xor	t5, t5, a1
	or	a0, t4, t5
	ret

	.align 2
trap_handler:
	csrr	s3, mcause
	csrr	s4, mtval
	li	t6, 9			# environment call from S
	beq	s3, t6, done_m
	addi	s5, s5, 1
	beqz	s6, 1f
	csrr	s9, VSTART
	sd	s6, 0(s7)
	sfence.vma
	li	s6, 0
	mret
1:	csrr	t6, mepc
	addi	t6, t6, 4
	csrw	mepc, t6
	mret
done_m:
	la	t0, tohost
	sd	a0, 0(t0)
9:	j	9b

	.section .tohost,"aw",@progbits
	.align 6
	.globl tohost
tohost:	.dword 0
	.globl fromhost
fromhost:
	.dword 0

	.section .data
	.align 12
pt2:	.zero 4096
pt1:	.zero 4096
pt0:	.zero 4096
pagea:	.zero 4096
pageb:	.zero 4096
dst:	.zero 16
	.align 4
src:
	.byte	0x01, 0x08, 0x0f, 0x16, 0x1d, 0x24, 0x2b, 0x32, 0x39, 0x40, 0x47, 0x4e, 0x55, 0x5c, 0x63, 0x6a
	.byte	0x71, 0x78, 0x7f, 0x86, 0x8d, 0x94, 0x9b, 0xa2, 0xa9, 0xb0, 0xb7, 0xbe, 0xc5, 0xcc, 0xd3, 0xda
	.byte	0xe1, 0xe8, 0xef, 0xf6, 0xfd, 0x04, 0x0b, 0x12, 0x19, 0x20, 0x27, 0x2e, 0x35, 0x3c, 0x43, 0x4a
	.byte	0x51, 0x58, 0x5f, 0x66, 0x6d, 0x74, 0x7b, 0x82, 0x89, 0x90, 0x97, 0x9e, 0xa5, 0xac, 0xb3, 0xba
	.byte	0xc1, 0xc8, 0xcf, 0xd6, 0xdd, 0xe4, 0xeb, 0xf2, 0xf9, 0x00, 0x07, 0x0e, 0x15, 0x1c, 0x23, 0x2a
	.byte	0x31, 0x38, 0x3f, 0x46, 0x4d, 0x54, 0x5b, 0x62, 0x69, 0x70, 0x77, 0x7e, 0x85, 0x8c, 0x93, 0x9a
	.byte	0xa1, 0xa8, 0xaf, 0xb6, 0xbd, 0xc4, 0xcb, 0xd2, 0xd9, 0xe0, 0xe7, 0xee, 0xf5, 0xfc, 0x03, 0x0a
	.byte	0x11, 0x18, 0x1f, 0x26, 0x2d, 0x34, 0x3b, 0x42, 0x49, 0x50, 0x57, 0x5e, 0x65, 0x6c, 0x73, 0x7a
	.byte	0x81, 0x88, 0x8f, 0x96, 0x9d, 0xa4, 0xab, 0xb2, 0xb9, 0xc0, 0xc7, 0xce, 0xd5, 0xdc, 0xe3, 0xea
	.byte	0xf1, 0xf8, 0xff, 0x06, 0x0d, 0x14, 0x1b, 0x22, 0x29, 0x30, 0x37, 0x3e, 0x45, 0x4c, 0x53, 0x5a
	.byte	0x61, 0x68, 0x6f, 0x76, 0x7d, 0x84, 0x8b, 0x92, 0x99, 0xa0, 0xa7, 0xae, 0xb5, 0xbc, 0xc3, 0xca
	.byte	0xd1, 0xd8, 0xdf, 0xe6, 0xed, 0xf4, 0xfb, 0x02, 0x09, 0x10, 0x17, 0x1e, 0x25, 0x2c, 0x33, 0x3a
	.byte	0x41, 0x48, 0x4f, 0x56, 0x5d, 0x64, 0x6b, 0x72, 0x79, 0x80, 0x87, 0x8e, 0x95, 0x9c, 0xa3, 0xaa
	.byte	0xb1, 0xb8, 0xbf, 0xc6, 0xcd, 0xd4, 0xdb, 0xe2, 0xe9, 0xf0, 0xf7, 0xfe, 0x05, 0x0c, 0x13, 0x1a
	.byte	0x21, 0x28, 0x2f, 0x36, 0x3d, 0x44, 0x4b, 0x52, 0x59, 0x60, 0x67, 0x6e, 0x75, 0x7c, 0x83, 0x8a
	.byte	0x91, 0x98, 0x9f, 0xa6, 0xad, 0xb4, 0xbb, 0xc2, 0xc9, 0xd0, 0xd7, 0xde, 0xe5, 0xec, 0xf3, 0xfa
